"""
title: Exportar Minuta de Impugnacao Servfaz
description: Após confirmação humana, gera o .docx timbrado a partir da minuta aprovada na resposta selecionada.
author: Servfaz
version: 2.3.0
requirements: python-docx==1.1.2
"""
# Arquivo gerado por build/montar_acao.py. Não edite à mão.
# Compatibilidade alvo: Open WebUI 0.12.3.
import asyncio
import base64
import hashlib
import io
import re
import unicodedata
from types import SimpleNamespace
from typing import Optional

from fastapi import UploadFile
from pydantic import BaseModel, Field
from starlette.datastructures import Headers

from docx import Document
from docx.enum.text import WD_COLOR_INDEX
from docx.oxml import OxmlElement
from docx.oxml.ns import qn
from docx.shared import Cm, Pt

from open_webui.routers.files import upload_file_handler



class Refusal(Exception):
    """Entrada que não pode virar minuta; a mensagem diz o que corrigir."""


# O catálogo de fontes é interno da triagem: nenhum ID, marcador [ID · status] ou menção a ele ou aos arquivos do estudo
# chega à minuta. "Catálogo" sozinho não conta: um edital pode citar o Catálogo de Serviços.
INTERNAL = re.compile(r'\b(?:EXT|INT|NOVA)-[A-Z0-9]|\[[^\]\n]*·[^\]\n]*\]|cat[aá]logo[ -]de[ -]fontes|'
                      r'(?:catalogo|indice)-fontes|references/estudo|\b[a-z]+/(?:fontes|analise|estrutura)\.md', re.I)

# Nomes em ASCII: o nome do estilo vira o styleId no XML, e leitores de .docx tropeçam em acento ali.
STYLES = {'corpo': 'Peca Corpo', 'titulo': 'Peca Titulo', 'subtitulo': 'Peca Subtitulo', 'citacao': 'Peca Citacao',
          'alinea': 'Peca Alinea', 'centro': 'Peca Centro', 'tabela': 'Peca Tabela'}
ROMAN_NUMBERING, ALINEA_NUMBERING = 'PecaSecao', 'PecaAlinea'
MESES = ('janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho', 'agosto', 'setembro', 'outubro',
         'novembro', 'dezembro')
# Rótulo do "[Inserir ...]" (sem acento, minúsculo) -> chave de dados-servfaz.json.
CAMPOS = {'razao social': 'razao_social', 'razao social da empresa': 'razao_social',
          'razao social da empresa impugnante': 'razao_social', 'cnpj': 'cnpj', 'endereco': 'endereco',
          'endereco completo': 'endereco', 'local': 'local', 'cpf': 'cpf', 'rg': 'rg', 'nome': 'nome',
          'nome do representante': 'nome', 'nome do representante legal': 'nome', 'representante': 'nome',
          'representante legal': 'nome', 'cargo': 'cargo', 'cargo do representante': 'cargo',
          'cargo do representante legal': 'cargo'}
CAMPO = re.compile(r'\[inserir ([^\]\n]+)\]', re.I)
CAMPO_DATA = re.compile(r'\[data(?: do protocolo| da pe[cç]a)?\]', re.I)
ITEM = re.compile(r'^\d+\.\s+(.*)$')
BOLD_LINE = re.compile(r'^\*\*[^*]+\*\*$')
INLINE = re.compile(r'(\*\*.+?\*\*|(?<![\w*])\*(?!\*)[^*]+?\*(?![\w*])|(?<![\w*])_(?!_).+?(?<!_)_(?!\w))')
HEADING = re.compile(r'^(#{1,6})\s+(.*)$')
ROMAN = re.compile(r'^[IVXL]+\.\s+')
BULLET = re.compile(r'^\s*[-*+]\s+(.*)$')
RULE = re.compile(r'^(?:-{3,}|\*{3,})$')
MARKER = re.compile(r'^\**[a-z0-9]+\)\**\s')
SUB_INDENT = Cm(2.25)
FRONT = re.compile(r'\A---\n.*?\n---\n', re.S)
CENTER_ON, CENTER_OFF = '<!-- centralizado -->', '<!-- /centralizado -->'


def add_text(paragraph, text, **fmt):
    """Texto em um ou mais trechos; o campo em branco sai com destaque amarelo."""
    for piece in re.split(f'({PENDENTE.pattern})', text, flags=re.I):
        if not piece:
            continue
        run = paragraph.add_run(piece)
        for name, value in fmt.items():
            setattr(run, name, value)
        if PENDENTE.fullmatch(piece):
            run.font.highlight_color = WD_COLOR_INDEX.YELLOW


def add_runs(paragraph, text):
    for part in INLINE.split(text):
        if not part:
            continue
        if part.startswith('**') and part.endswith('**') and len(part) > 4:
            add_text(paragraph, part[2:-2], bold=True)
        elif part[0] in '*_' and part[-1] == part[0] and len(part) > 2:
            add_text(paragraph, part[1:-1], italic=True)
        else:
            add_text(paragraph, part)
    return paragraph


def new_list(doc):
    """Nova numeração a), b) que recomeça em a): um w:num por lista, com startOverride."""
    numbering = doc.part.numbering_part.element
    abstract_id = None
    for abstract in numbering.findall(qn('w:abstractNum')):
        name = abstract.find(qn('w:name'))
        if name is not None and name.get(qn('w:val')) == ALINEA_NUMBERING:
            abstract_id = abstract.get(qn('w:abstractNumId'))
    if abstract_id is None:
        raise Refusal(f'o timbre não tem a numeração {ALINEA_NUMBERING}: gere-o com criar_timbre.py.')
    num_id = max([int(n.get(qn('w:numId'))) for n in numbering.findall(qn('w:num'))], default=0) + 1
    num = OxmlElement('w:num')
    num.set(qn('w:numId'), str(num_id))
    ref = OxmlElement('w:abstractNumId')
    ref.set(qn('w:val'), abstract_id)
    override = OxmlElement('w:lvlOverride')
    override.set(qn('w:ilvl'), '0')
    start = OxmlElement('w:startOverride')
    start.set(qn('w:val'), '1')
    override.append(start)
    num.extend([ref, override])
    numbering.append(num)
    return num_id


def number_paragraph(paragraph, num_id):
    numpr = OxmlElement('w:numPr')
    for tag, value in (('w:ilvl', '0'), ('w:numId', str(num_id))):
        node = OxmlElement(tag)
        node.set(qn('w:val'), value)
        numpr.append(node)
    paragraph._p.get_or_add_pPr().append(numpr)


def add_table(doc, lines):
    rows = [[cell.strip() for cell in line.strip().strip('|').split('|')] for line in lines]
    rows = [row for row in rows if not all(re.fullmatch(r':?-+:?', cell) for cell in row)]
    if not rows or not rows[0]:
        raise Refusal('a tabela Markdown está vazia.')
    if any(len(row) != len(rows[0]) for row in rows):
        raise Refusal('a tabela Markdown tem linhas com quantidades diferentes de colunas.')
    table = doc.add_table(rows=len(rows), cols=len(rows[0]))
    borders = OxmlElement('w:tblBorders')
    for side in ('top', 'left', 'bottom', 'right', 'insideH', 'insideV'):
        edge = OxmlElement(f'w:{side}')
        for key, value in (('val', 'single'), ('sz', '4'), ('space', '0'), ('color', '000000')):
            edge.set(qn(f'w:{key}'), value)
        borders.append(edge)
    table._tbl.tblPr.append(borders)
    for r, row in enumerate(rows):
        for c, text in enumerate(row):
            paragraph = table.cell(r, c).paragraphs[0]
            paragraph.style = STYLES['tabela']
            add_runs(paragraph, f'**{text}**' if r == 0 and text else text)
    header = OxmlElement('w:tblHeader')
    table.rows[0]._tr.get_or_add_trPr().append(header)
    doc.add_paragraph(style=STYLES['corpo'])


def add_sub_items(doc, subs):
    for sub in subs:
        text = sub if MARKER.match(sub) else f'– {sub}'
        paragraph = add_runs(doc.add_paragraph(style=STYLES['alinea']), text)
        paragraph.paragraph_format.left_indent = SUB_INDENT


def close_last(items):
    """O último item do pedido termina em ponto final, mesmo que o texto traga ';'."""
    last = items[-1]
    if last[1]:
        last[1][-1] = re.sub(r';\s*$', '.', last[1][-1])
    else:
        last[0] = re.sub(r';\s*$', '.', last[0])


def build(doc, text):
    lines = text.split('\n')
    centered, i = False, 0
    blank = ('', CENTER_ON, CENTER_OFF)
    while i < len(lines):
        line = lines[i].strip()
        following = lines[i + 1].strip() if i + 1 < len(lines) else ''
        i += 1
        if not line or RULE.match(line):
            continue
        if line in (CENTER_ON, CENTER_OFF):
            centered = line == CENTER_ON
            continue
        heading = HEADING.match(line)
        if heading:
            level, title = len(heading[1]), heading[2].strip()
            if level == 2:
                paragraph = add_runs(doc.add_paragraph(style=STYLES['centro']), title)
                for run in paragraph.runs:
                    run.bold = True
            elif level == 4:
                add_runs(doc.add_paragraph(style=STYLES['subtitulo']), title)
            else:
                add_runs(doc.add_paragraph(style=STYLES['titulo']), ROMAN.sub('', title))
            continue
        if line.startswith('|'):
            block = [line]
            while i < len(lines) and lines[i].strip().startswith('|'):
                block.append(lines[i].strip())
                i += 1
            add_table(doc, block)
            continue
        if ITEM.match(line):
            items = [[ITEM.match(line)[1], []]]
            while i < len(lines):
                if ITEM.match(lines[i].strip()):
                    items.append([ITEM.match(lines[i].strip())[1], []])
                elif BULLET.match(lines[i]):
                    items[-1][1].append(BULLET.match(lines[i])[1].strip())
                else:
                    break
                i += 1
            close_last(items)
            num_id = new_list(doc)
            for item, subs in items:
                number_paragraph(add_runs(doc.add_paragraph(style=STYLES['alinea']), item), num_id)
                add_sub_items(doc, subs)
            continue
        if BULLET.match(lines[i - 1]):
            bullets = [BULLET.match(lines[i - 1])[1].strip()]
            while i < len(lines) and BULLET.match(lines[i]):
                bullets.append(BULLET.match(lines[i])[1].strip())
                i += 1
            if all(MARKER.match(b) for b in bullets):  # já trazem a), b) digitado: só recuo
                add_sub_items(doc, bullets)
            else:
                items = [[b, []] for b in bullets]
                close_last(items)
                num_id = new_list(doc)
                for item, _ in items:
                    number_paragraph(add_runs(doc.add_paragraph(style=STYLES['alinea']), item), num_id)
            continue
        if line.startswith('>'):
            add_runs(doc.add_paragraph(style=STYLES['citacao']), line[1:].strip())
            continue
        style = STYLES['centro'] if centered else STYLES['subtitulo'] if BOLD_LINE.match(line) else STYLES['corpo']
        paragraph = add_runs(doc.add_paragraph(style=style), line)
        if following and following not in blank and not RULE.match(following):
            paragraph.paragraph_format.space_after = Pt(0)


# Campo em branco: não barra a geração; sai em destaque no .docx e entra na lista de pendências.
PENDENTE = re.compile(r'\{\{[^}\n]*\}\}|\[(?:inserir|preencher|informar|data|nome|cnpj|cpf|endere[cç]o)\b[^\]\n]*\]', re.I)
# Marcador de citação do chat do Open WebUI ([1], [1, 2], [1][2]): aponta para o painel de fontes da conversa e não
# significa nada no .docx. A referência sai por extenso, como (Edital, item 13.1, pág. 26).
CITACAO_CHAT = re.compile(r'\[\d{1,3}(?:\s*,\s*\d{1,3})*\]')
# Marcação que o conversor não trata.
UNSUPPORTED = re.compile(r'^\s*```|^#{5,}\s|!\[[^\]\n]*\]\(|\[[^\]\n]+\]\([^)\n]+\)|</?[a-z][^>\n]*>|~~', re.I)


def preencher(text, dados, when=None):
    """Preenche só os campos "[Inserir ...]" que os dados conhecem e a data; o resto fica para a trava."""
    def campo(match):
        label = unicodedata.normalize('NFKD', match[1]).encode('ascii', 'ignore').decode().lower().strip()
        return dados.get(CAMPOS.get(label)) or match[0]

    text = CAMPO.sub(campo, text)
    if when:
        text = CAMPO_DATA.sub(f'{when.day} de {MESES[when.month - 1]} de {when.year}', text)
    return text


def check_clean(text, label):
    """A trava: a minuta não sai com referência interna da triagem nem marcação que o conversor não trata. Cada achado leva a linha, para o analista corrigir o Markdown."""
    problems = []
    for number, line in enumerate(text.split('\n'), 1):
        for regex, what in ((INTERNAL, 'referência interna'),
                            (UNSUPPORTED, 'marcação que o conversor não trata'),
                            (CITACAO_CHAT, 'marcador de citação do chat; use a referência por extenso')):
            found = regex.search(line)
            if found:
                problems.append(f'linha {number}: {what} "{found[0].strip()}"')
    if problems:
        raise Refusal(f'{label} não pode sair assim: ' + '; '.join(problems[:10]) +
                      (f'; e mais {len(problems) - 10}' if len(problems) > 10 else '') +
                      '. Corrija o Markdown e gere de novo.')
    return text


def pendencias(text):
    """Campos em branco que sobraram, como (linha, marcador), para o analista preencher no Word."""
    return [(number, found[0]) for number, line in enumerate(text.split('\n'), 1) for found in PENDENTE.finditer(line)]


def render(text, timbre, dados=None, when=None, label='a minuta'):
    """Markdown -> (Document, pendências). ``timbre`` aceita caminho ou arquivo binário aberto."""
    text = preencher(unicodedata.normalize('NFC', text), dados or {}, when)
    check_clean(text, label)
    text = FRONT.sub('', text, count=1)
    doc = Document(timbre)
    build(doc, text)
    return doc, pendencias(text)


OPENWEBUI_COMPATIBILITY = '0.12.3'
DOCX = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
INICIO = '<!-- minuta-servfaz:inicio -->'
FIM = '<!-- minuta-servfaz:fim -->'
_BLOCO = re.compile(re.escape(INICIO) + r'\s*(.*?)\s*' + re.escape(FIM), re.S)


def nome_seguro(nome):
    """Nome de arquivo só com letras, números, ponto, hífen e sublinhado; sempre termina em .docx."""
    base = unicodedata.normalize('NFKD', nome or '').encode('ascii', 'ignore').decode()
    base = re.sub(r'[^\w.-]+', '-', re.sub(r'\.docx$', '', base.strip(), flags=re.I)).strip('.-_')
    return (base or 'minuta-impugnacao') + '.docx'


def extrair_minuta(content):
    """Lê um único bloco explícito de minuta na resposta que recebeu a Action."""
    matches = _BLOCO.findall(content or '')
    if len(matches) != 1:
        raise Refusal('a resposta selecionada precisa conter exatamente um bloco entre '
                      f'{INICIO} e {FIM}. Revise a minuta antes de exportar.')
    markdown = matches[0].strip()
    if not markdown:
        raise Refusal('o bloco da minuta aprovada está vazio.')
    return markdown


def mensagem_alvo(body):
    target_id = body.get('id')
    for message in body.get('messages') or []:
        if message.get('id') == target_id:
            if message.get('role') != 'assistant':
                raise Refusal('a Action só exporta uma resposta do assistente.')
            return message.get('content') or ''
    raise Refusal('não foi possível localizar a resposta selecionada para exportação.')


def ator(user):
    if not isinstance(user, dict) or not user.get('id'):
        raise Refusal('não foi possível identificar o usuário que solicitou a exportação.')
    # upload_file_handler só necessita destes atributos na criação do arquivo. Os dados do signatário ficam fora
    # dos metadados do arquivo.
    return SimpleNamespace(id=str(user['id']), email=str(user.get('email') or ''),
                           name=str(user.get('name') or user.get('username') or ''),
                           role=str(user.get('role') or 'user'))


async def avisar(emitter, kind, content):
    if emitter:
        await emitter({'type': 'notification', 'data': {'type': kind, 'content': content}})


class Action:
    class Valves(BaseModel):
        RAZAO_SOCIAL: str = Field('', description='Razão social da Servfaz; preenche [Inserir Razão Social...].')
        CNPJ: str = Field('', description='CNPJ da Servfaz; preenche apenas [Inserir CNPJ].')
        ENDERECO: str = Field('', description='Endereço da Servfaz; preenche [Inserir Endereço] quando existir.')
        LOCAL: str = Field('', description='Cidade/UF do fecho; preenche [Inserir Local].')
        REPRESENTANTE_NOME: str = Field('', description='Nome do representante legal; preenche [Inserir Nome do '
                                                        'Representante] e variações.')
        REPRESENTANTE_CARGO: str = Field('', description='Cargo do representante; preenche [Inserir Cargo do '
                                                         'Representante].')
        REPRESENTANTE_RG: str = Field('', description='RG do representante; preenche [Inserir RG].')
        REPRESENTANTE_CPF: str = Field('', description='CPF do representante; preenche [Inserir CPF].')
        priority: int = 10

    def __init__(self):
        self.valves = self.Valves()

    async def action(self, body: dict, __user__=None, __request__=None, __event_emitter__=None,
                     __event_call__=None):
        """Gera um DOCX da resposta aprovada, após confirmação explícita do analista.

        A resposta deve conter somente um bloco da forma:
        <!-- minuta-servfaz:inicio -->
        ... Markdown aprovado ...
        <!-- minuta-servfaz:fim -->
        """
        try:
            markdown = extrair_minuta(mensagem_alvo(body))
            check_clean(markdown, 'a minuta selecionada')
        except Refusal as exc:
            await avisar(__event_emitter__, 'error', str(exc))
            return

        digest = hashlib.sha256(markdown.encode('utf-8')).hexdigest()
        if not __event_call__:
            await avisar(__event_emitter__, 'error', 'a confirmação no navegador é obrigatória para exportar a minuta.')
            return
        confirmation = await __event_call__({
            'type': 'confirmation',
            'data': {
                'title': 'Confirmar geração da minuta',
                'message': ('Será gerado um .docx do texto exatamente como aparece no bloco aprovado. '
                            f'Hash da versão: {digest[:12]}. A Action não assina nem protocola a peça.')
            }
        })
        if not confirmation or (isinstance(confirmation, dict) and confirmation.get('error')):
            await avisar(__event_emitter__, 'warning', 'Geração cancelada ou confirmação indisponível; nenhum arquivo foi criado.')
            return

        try:
            v = self.valves
            dados = {'razao_social': v.RAZAO_SOCIAL, 'cnpj': v.CNPJ, 'endereco': v.ENDERECO, 'local': v.LOCAL,
                     'nome': v.REPRESENTANTE_NOME, 'cargo': v.REPRESENTANTE_CARGO, 'rg': v.REPRESENTANTE_RG,
                     'cpf': v.REPRESENTANTE_CPF}
            doc, pending = render(markdown, io.BytesIO(base64.b64decode(_TIMBRE_B64)), dados,
                                  label='a minuta selecionada')
            buffer = io.BytesIO()
            doc.save(buffer)
            contents = buffer.getvalue()
            filename = nome_seguro(f'minuta-impugnacao-{digest[:12]}')
            upload = UploadFile(file=io.BytesIO(contents), filename=filename,
                                headers=Headers({'content-type': DOCX}))
            result = await upload_file_handler(__request__, file=upload,
                                               metadata={'source': 'exportar-minuta-servfaz',
                                                         'markdown_sha256': digest},
                                               process=False, process_in_background=False, user=ator(__user__))
            item = result.model_dump() if hasattr(result, 'model_dump') else dict(result)
            file_id = item['id']
        except (OSError, Refusal, ValueError, KeyError) as exc:
            await avisar(__event_emitter__, 'error', f'Não foi possível gerar a minuta: {exc}')
            return
        except Exception:
            await avisar(__event_emitter__, 'error', 'Não foi possível guardar o .docx no Open WebUI. Consulte o log do servidor.')
            raise

        await __event_emitter__({
            'type': 'files',
            'data': {'files': [{
                'type': 'file',
                'id': file_id,
                'name': filename,
                'url': f'/api/v1/files/{file_id}/content',
                'meta': {'name': filename, 'content_type': DOCX, 'size': len(contents),
                         'markdown_sha256': digest}
            }]}
        })
        detail = (f'{len(pending)} campo(s) ficaram destacados em amarelo no Word.' if pending
                  else 'Nenhum campo de preenchimento ficou pendente.')
        await avisar(__event_emitter__, 'success', f'Minuta gerada: {filename}. {detail} Revise, assine e protocole fora do sistema.')


